package org.example.api.quotation;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import org.example.config.ConfigManager;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
public final class QuotationApiClient{private final HttpClient http = org.example.api.ApiRuntime.HTTP;private final ObjectMapper json = org.example.api.ApiRuntime.JSON;public QuotationApiClient(){}
 public List<QuoteDto> list(){return get("/api/quotations",new TypeReference<List<QuoteDto>>(){});}public Page page(int page,int size,String q,String number,String customer,String status,String from,String to,String valid,String salesperson,String minAmount,String maxAmount,String followUp,String source){return get("/api/quotations/page?page="+Math.max(0,page)+"&size="+Math.max(10,Math.min(size,200))+"&q="+enc(q)+"&number="+enc(number)+"&customer="+enc(customer)+"&status="+enc(status)+"&from="+enc(from)+"&to="+enc(to)+"&valid="+enc(valid)+"&salesperson="+enc(salesperson)+"&minAmount="+enc(minAmount)+"&maxAmount="+enc(maxAmount)+"&followUp="+enc(followUp)+"&source="+enc(source),Page.class);}public QuoteDto quote(int id){return get("/api/quotations/"+id,QuoteDto.class);}public List<QuoteDto> allFiltered(String q,String number,String customer,String status,String from,String to,String valid,String salesperson,String minAmount,String maxAmount,String followUp,String source){Page first=page(0,200,q,number,customer,status,from,to,valid,salesperson,minAmount,maxAmount,followUp,source);List<QuoteDto> out=new ArrayList<>(first.rows()==null?List.of():first.rows());for(int p=1;p<first.totalPages();p++){Page next=page(p,200,q,number,customer,status,from,to,valid,salesperson,minAmount,maxAmount,followUp,source);if(next.rows()!=null)out.addAll(next.rows());}return out;}public List<LineDto> lines(int id){return get("/api/quotations/"+id+"/lines",new TypeReference<List<LineDto>>(){});}public List<String> sources(){return get("/api/quotations/sources",new TypeReference<List<String>>(){});}public List<ItemChoiceDto> searchItems(String q,int limit){return get("/api/quotations/items/search?q="+enc(q)+"&limit="+Math.max(1,Math.min(limit,50)),new TypeReference<List<ItemChoiceDto>>(){});}public QuoteDto save(SaveRequest d){return d.id()==null?post("/api/quotations",d,QuoteDto.class):put("/api/quotations/"+d.id(),d,QuoteDto.class);}public void notes(int id,String v){put("/api/quotations/"+id+"/notes",new Text(v),Ok.class);}public void markSent(int id,String channel){postNoBody("/api/quotations/"+id+"/sent?channel="+enc(channel));}public void followUp(int id,String date,String notes){post("/api/quotations/"+id+"/follow-up",new FollowUp(date,notes),Ok.class);}public String convert(int id,String user){return post("/api/quotations/"+id+"/convert?user="+enc(user),null,Text.class).value();}public String duplicate(int id,String user){return post("/api/quotations/"+id+"/duplicate?user="+enc(user),null,Text.class).value();}public void delete(int id){deleteReq("/api/quotations/"+id);}
 private <T>T get(String p,Class<T>c){return req("GET",p,null,c,null);}private <T>T get(String p,TypeReference<T>t){return req("GET",p,null,null,t);}private <T>T post(String p,Object b,Class<T>c){return req("POST",p,b,c,null);}private <T>T put(String p,Object b,Class<T>c){return req("PUT",p,b,c,null);}private void postNoBody(String p){req("POST",p,null,Ok.class,null);}private void deleteReq(String p){req("DELETE",p,null,Ok.class,null);}private <T>T req(String m,String p,Object body,Class<T>c,TypeReference<T>t){try{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(base()+p)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");org.example.api.ApiSession.authorize(b);if(body!=null)b.header("Content-Type","application/json").method(m,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else b.method(m,HttpRequest.BodyPublishers.noBody());var r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()==401)throw org.example.api.ApiSession.rejected("Quotation request",r.body());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("Quotation API error ("+r.statusCode()+"): "+r.body());return t!=null?json.readValue(r.body(),t):json.readValue(r.body(),c);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}catch(IOException e){throw new IllegalStateException("Cannot reach quotation API at "+base(),e);}}private String base(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);return b;}private String enc(String v){return URLEncoder.encode(v==null?"":v,StandardCharsets.UTF_8);}
 public record QuoteDto(int id,int customerId,String no,String date,String customer,String valid,String status,String followUp,String converted,String salesperson,String createdBy,double amount,String phone,String email,String gstin,String source,String remarks,double discount,String attachment){}public record LineDto(String code,String description,double quantity,double rate,double gst,double discount,double total){}public record ItemChoiceDto(String code,String description,String remarks,String hsn,double rate,double gst,double discount){}public record SaveRequest(Integer id,String date,String valid,int customerId,double subtotal,double discountAmount,double gstAmount,double total,String remarks,String followUp,String salesperson,String source,String createdBy,List<LineDto> lines){}public record FollowUp(String date,String notes){}public record Text(String value){}public record MetricPoint(String label,double value){}public record Metrics(double totalValue,long totalCount,double pendingValue,long pendingCount,double acceptedValue,long acceptedCount,double expiredValue,long expiredCount,double conversionRate,double average,List<MetricPoint> trend,List<MetricPoint> statuses){}public record Page(List<QuoteDto> rows,int page,int size,long totalRows,int totalPages,double filteredAmount,Metrics metrics,List<String> customers,List<String> salespersons){}public record Ok(boolean success,String message){}
}
